body { margin: 0px; padding: 0px; }
main { display: block; }
h1 { margin: 0.67em 0px; font-size: 2em; }
hr { box-sizing: content-box; height: 0px; overflow: visible; }
th, tr { margin: 0px; padding: 0px; }
pre { font-family: monospace; font-size: 1em; }
a { background-color: transparent; }
abbr[title] { border-bottom: none; text-decoration: underline dotted; }
code, kbd, samp { font-family: monospace; font-size: 1em; }
img { border-style: none; }
button, input, optgroup, select, textarea { margin: 0px; font-family: inherit; line-height: 1.15; }
button, input { overflow: visible; }
button { appearance: button; }
[type="button"] { appearance: button; }
[type="reset"] { appearance: button; }
[type="submit"] { appearance: button; }
fieldset { padding: 0.35em 0.75em 0.625em; }
legend { box-sizing: border-box; color: inherit; white-space: normal; max-width: 100%; padding: 0px; display: table; }
textarea { overflow: auto; }
[type="checkbox"] { box-sizing: border-box; padding: 0px; }
[type="radio"] { box-sizing: border-box; padding: 0px; }
[type="number"]::-webkit-inner-spin-button { height: auto; }
[type="number"]::-webkit-outer-spin-button { height: auto; }
[type="search"]::-webkit-search-decoration { appearance: none; }
details { display: block; }
template, [hidden] { display: none; }
* { outline: 0px; }
.arco-icon { color: inherit; vertical-align: -2px; stroke: currentcolor; width: 1em; height: 1em; font-style: normal; display: inline-block; }
.arco-icon[fill="currentColor"] { fill: currentcolor; stroke: none; }
.arco-icon[stroke="currentColor"] { stroke: currentcolor; fill: none; }
.arco-icon[fill="currentColor"][stroke="currentColor"] { fill: currentcolor; stroke: currentcolor; }
.arco-icon-loading { animation: 1s cubic-bezier(0, 0, 1, 1) 0s infinite normal none running arco-loading-circle; }
@keyframes arco-loading-circle { 
