html, body, #root {
	width: 100%;
	height: 100%;
	margin: 0;
	padding: 0;
	overflow: hidden;
}
body {
	background-color: var(--vscode-icube-colorBg1);
	color: var(--vscode-foreground);
}

/* Font Families (with CJK support) */
@font-face {
	font-family: "JetBrains Mono";
	font-style: normal;
	src: url('../../../workbench/browser/media/JetBrainsMono-VariableFont_wght.ttf') format("truetype");
	/* ignore: U+2937 ('⤷') */
	unicode-range: U+0-2936, U+2938-10FFFF;
}
/* AI 生成 2026-04-28: 语音讨论欢迎页斜体标题字体 */
@font-face {
	font-family: "Instrument Serif";
	font-style: italic;
	font-weight: 400;
	font-display: swap;
	src: url('../../../workbench/browser/media/InstrumentSerif-Italic.ttf') format("truetype");
}

